#include <vector>
#include <cstddef>
#include <limits>
#include <omp.h>

int edgeCount(std::vector<int> const& A, size_t N) {
    const size_t expected = N * N;
    const size_t total = (A.size() < expected) ? A.size() : expected;

    long long count = 0;

    #pragma omp parallel for reduction(+:count) schedule(static)
    for (long long idx = 0; idx < static_cast<long long>(total); ++idx) {
        count += (A[static_cast<size_t>(idx)] != 0) ? 1LL : 0LL;
    }

    if (count > static_cast<long long>(std::numeric_limits<int>::max())) {
        return std::numeric_limits<int>::max();
    }
    return static_cast<int>(count);
}
